import csv
from collections import defaultdict

# The claim: PPCI bias from 0.179 to 0.007 (R-learner)
# CausalForest: naive_forest extreme = 0.17985 ~= 0.180, and ec_hte_forest K=4 extreme n=500 sub=0 = 0.00795 ~= 0.008
# That's close: 0.180 and 0.008 but not exactly 0.179 and 0.007

# PPCI: ec_hte B_outcome_only moderate n=50 = 0.17892 ~= 0.179
# And what's the correction? ppci in B_outcome_only all conditions?

# Let me look at DGP B with ppci correction across all regimes
with open('/home/ubuntu/ec_hte_llm_annotation/results/exp007_ppci_dsl.csv') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# For PPCI experiment, the key comparison is ec_hte (uncorrected) vs ec_hte_ppci (corrected)
# DGP B_outcome_only:
print('=== DGP B_outcome_only: ec_hte vs ec_hte_ppci ===')
for n in ['50', '100', '250', '500']:
    for regime in ['extreme', 'moderate', 'homogeneous']:
        ec_vals = []
        ppci_vals = []
        for r in rows:
            if r['dgp'] == 'B_outcome_only' and r['n_expert'] == n and r['regime'] == regime:
                if r['method'] == 'ec_hte':
                    ec_vals.append(abs(float(r['bias_z0'])))
                    ec_vals.append(abs(float(r['bias_z1'])))
                elif r['method'] == 'ec_hte_ppci':
                    ppci_vals.append(abs(float(r['bias_z0'])))
                    ppci_vals.append(abs(float(r['bias_z1'])))
        if ec_vals and ppci_vals:
            ec_mean = sum(ec_vals)/len(ec_vals)
            ppci_mean = sum(ppci_vals)/len(ppci_vals)
            if abs(ec_mean - 0.179) < 0.005 or abs(ppci_mean - 0.007) < 0.005:
                print(f'  n={n}, {regime}: ec_hte={ec_mean:.6f}, ec_hte_ppci={ppci_mean:.6f}')

# Check all DGPs
print()
print('=== ALL: ec_hte vs ec_hte_ppci where ec_hte ~0.179 or ec_hte_ppci ~0.007 ===')
for dgp in sorted(set(r['dgp'] for r in rows)):
    for n in sorted(set(r['n_expert'] for r in rows), key=int):
        for regime in sorted(set(r['regime'] for r in rows)):
            for k in sorted(set(r['k_subgroups'] for r in rows)):
                for sigma in sorted(set(r['sigma_outcome'] for r in rows)):
                    ec_vals = []
                    ppci_vals = []
                    for r in rows:
                        if (r['dgp'] == dgp and r['n_expert'] == n and r['regime'] == regime 
                            and r['k_subgroups'] == k and r['sigma_outcome'] == sigma):
                            if r['method'] == 'ec_hte':
                                ec_vals.append(abs(float(r['bias_z0'])))
                                ec_vals.append(abs(float(r['bias_z1'])))
                            elif r['method'] == 'ec_hte_ppci':
                                ppci_vals.append(abs(float(r['bias_z0'])))
                                ppci_vals.append(abs(float(r['bias_z1'])))
                    if ec_vals and ppci_vals:
                        ec_mean = sum(ec_vals)/len(ec_vals)
                        ppci_mean = sum(ppci_vals)/len(ppci_vals)
                        if abs(ec_mean - 0.179) < 0.003 or abs(ppci_mean - 0.007) < 0.003:
                            print(f'  dgp={dgp}, n={n}, {regime}, k={k}, sigma={sigma}: ec_hte={ec_mean:.6f}, ec_hte_ppci={ppci_mean:.6f}')
